// Import needed libraries
const log = require('logToConsole');
const JSON = require('JSON');
const Object = require('Object');
const copyFromWindow = require('copyFromWindow');
const setInWindow = require('setInWindow');
const callInWindow = require('callInWindow');
const gtagSet = require('gtagSet');
const makeNumber = require('makeNumber');
const createQueue = require('createQueue');
const setDefaultConsentState = require('setDefaultConsentState');
const updateConsentState = require('updateConsentState');
const copyFromDataLayer = require('copyFromDataLayer');

// Config
const debug = typeof data.debug=='boolean' ? data.debug : false;

/**
 * Build aGTM shadow object
 * @property {object} o
 * @param {object} c - config
 * @param {object} c.debug - debug messages in browser console
 * @param {object} d - data object
 * @param {object} d.f - Events that have been fired before GTM has loaded
 * @param {object} d.q - event queue
 * @param {object} f - function library
 */
var o = o || { c: {debug:false}, d:{}, f:{} };
o.c.cm_signals = [
  'ad_storage',
  'ad_user_data',
  'ad_personalization',
  'analytics_storage',
  'personalization_storage',
  'functionality_storage',
  'security_storage'
];

// Get tag configuration
if (debug) log('info','Tag Configuration',data);
o.c.cm_update = typeof data.cm_update=='boolean' ? data.cm_update : false;
o.c.cm_update_after_default = typeof data.cm_update_after_default=='boolean' ? data.cm_update_after_default : false;
o.c.cm_attributes = data.cm_attributes || [];
o.c.cm_wait = typeof data.cm_wait=='string' ? makeNumber(data.cm_wait) : 0;
o.c.cm_regions = typeof data.cm_regions=='string' ? data.cm_regions : 'all';
o.c.url_passthrough = typeof data.url_passthrough=='boolean' ? data.url_passthrough : false;
o.c.ads_data_redaction = typeof data.ads_data_redaction=='boolean' ? data.ads_data_redaction : false;
o.c.ms_consent_mode = typeof data.ms_consent_mode=='boolean' ? data.ms_consent_mode : false;
o.c.cm_event = typeof data.cm_event=='boolean' ? data.cm_event : false;
o.c.cm_grant_outside = typeof data.cm_grant_outside=='boolean' ? data.cm_grant_outside : false;

// Fired by aGTM_consent_update, the tag is an Update whatever its configuration
// says (F-242). aGTM pushes that event when the visitor changes the consent on
// the page; a Default at that point is ignored by Consent Mode, so a tag that
// only ever set defaults left analytics_storage/personalization_storage at the
// page-load state until the next navigation - a withdrawal did not take effect
// for Analytics on the page it was made on. Treating the event as an Update
// lets ONE instance with a second trigger cover both moments, so the signal
// mapping exists once instead of in two instances that can drift apart. The
// update path already drops what an Update must not carry (gtagSet,
// wait_for_update, region) and switches Microsoft UET to 'update'.
o.c.update_event = copyFromDataLayer('event') === 'aGTM_consent_update';
if (o.c.update_event) {
  o.c.cm_update = true;
  o.c.cm_update_after_default = false;
  if (debug) log('info','Fired by aGTM_consent_update - sending a Consent Mode Update only');
}

// Get consent signals from aGTM. Guard against aGTM not being loaded yet
// (copyFromWindow returns undefined): without this, the .hasResponse access
// below throws a TypeError, so setDefaultConsentState/updateConsentState never
// run and NO deny-default is set - fail-open exactly in the consent-critical
// moment (e.g. when the tag fires on the Consent Initialization trigger before
// aGTM populated aGTM.d.consent). Fail closed: missing consent = {}.
var consent = copyFromWindow('aGTM.d.consent') || {};
if (debug) log('info','aGTM Consent Info', JSON.parse(JSON.stringify(consent)));

// Run Consent Check Fallback: when aGTM has no valid consent response yet, ask
// the CMP directly, THEN re-read the freshly written consent so the signal
// computation below actually uses it (the copy taken above is stale and would
// otherwise ignore what consent_check just wrote). No debug gating - the
// fallback must run in production too.
if (typeof consent.hasResponse!='boolean' || !consent.hasResponse) {
  const c_check = callInWindow('aGTM.f.consent_check', 'init');
  if (debug) log('info','consent_check Info', c_check);
  consent = copyFromWindow('aGTM.d.consent') || consent;
}

// Helper function to check a defined consent in aGTM
o.f.chk_cons = function (consKey, consVal) {
  if (typeof consent[consKey]!='string') return false;
  return consent[consKey].indexOf(consVal)>=0 ? true : false;
};

// Program
o.d.cm = {};
for (var i=0; i<o.c.cm_signals.length; i++) {
  var s = o.c.cm_signals[i];
  var c = '';
  if (o.c.cm_attributes.length>0) {
    for (var j=0; j<o.c.cm_attributes.length; j++) {
      var a = o.c.cm_attributes[j];
      if (a.cm_attribute==s && c!='denied') {
        c = o.f.chk_cons(a.cm_type,a.cm_value) ? 'granted' : 'denied';
      }
    }
  }
  if (!c && data[s]=='not_set') continue;
  o.d.cm[s] = c ? c : data[s];
}
if (!o.c.cm_update && o.c.cm_wait>0 && !o.c.cm_update_after_default) o.d.cm.wait_for_update = o.c.cm_wait;
if (!o.c.cm_update && o.c.cm_regions!='all' && o.c.cm_regions) {
  o.d.cm.region = o.c.cm_regions.split(',').map(r => r.trim());
  o.d.cm.region = o.d.cm.region.filter((val, idx) => o.d.cm.region.indexOf(val) === idx);
  if (debug) log('info','CM Regions', o.d.cm.region);
}

// Fire Consent Mode dataLayer Event
if (o.c.cm_event) {
  const c_ev = { event:'aGTM_consent_mode', cm_signals:o.d.cm };
  // Uses aGTM.f.fire rather than a raw dataLayer push, so the signal event lands in
  // aGTM's event log and goes out through sendnaus() with its dataLayer-hook protection.
  // Note it is NOT consent-gated or queued: fire() lets any event whose name starts with
  // "aGTM" past both, which is what this signal needs — it has to reach GTM before the
  // consent decision. That is also why the template needs no access_globals grant on the
  // global dataLayer (gtagSet's writes are covered by write_data_layer instead).
  callInWindow('aGTM.f.fire', c_ev);
}

// Other settings
if (!o.c.cm_update) {
  gtagSet({
    url_passthrough: o.c.url_passthrough,
    ads_data_redaction: o.c.ads_data_redaction
  });
}

// Set the consent state
if (o.c.cm_update) {
  updateConsentState(o.d.cm);
  if (debug) log('info','Consent Update', JSON.parse(JSON.stringify(o.d.cm)));
} else {
  // Optional GLOBAL granted fallback (Google's two-default pattern): when a
  // specific region is configured (o.d.cm.region present) and cm_grant_outside
  // is on, emit a global granted default (no region) FIRST so visitors OUTSIDE
  // the configured regions are granted by default instead of being left unset
  // (Consent Mode treats a region-scoped-only default as undefined elsewhere).
  // The region-scoped default set below is more specific and wins inside the
  // regions. Without this, "everything allowed outside the regions" relied
  // solely on the update firing granted in time.
  if (o.c.cm_grant_outside && o.d.cm.region) {
    o.d.cmg = {};
    // Grant ONLY the signals the region-scoped default below actually covers
    // (i.e. those present in o.d.cm). Signals left at "not_set" are excluded
    // from o.d.cm (see the `not_set` skip above), so granting all 7 here would
    // make Consent Mode's per-signal merge fall those not_set signals back to
    // this global granted value INSIDE the deny region too - a fail-open. By
    // mirroring o.d.cm's signal set, every signal the regional default covers
    // wins in-region, and not_set signals stay unset everywhere.
    for (var gi=0; gi<o.c.cm_signals.length; gi++) {
      var gsig = o.c.cm_signals[gi];
      if (typeof o.d.cm[gsig] != 'undefined') o.d.cmg[gsig] = 'granted';
    }
    setDefaultConsentState(o.d.cmg);
    if (debug) log('info','Consent Global Granted Default (outside regions)', JSON.parse(JSON.stringify(o.d.cmg)));
  }
  if (o.c.cm_update_after_default) {
    o.d.cmd = {};
    for (var i=0; i<o.c.cm_signals.length; i++) {
      var s = o.c.cm_signals[i];
      o.d.cmd[s] = 'denied';
    }
    // Region belongs on the DEFAULT: `region` is only valid on
    // setDefaultConsentState, not updateConsentState (the update is already
    // location-independent). Without this the all-denied default applied
    // GLOBALLY - a configured cm_regions was silently ignored, so the deny
    // baseline hit visitors outside the intended regions too (F-31c). Scoping
    // the denied default to cm_regions means the region-less update below sets
    // the real consent per user everywhere else. NOTE: outside the region there
    // is now no aGTM default (Consent Mode treats unset per Google's rules); the
    // region-less updateConsentState provides the actual state for those users.
    if (o.d.cm.region) o.d.cmd.region = o.d.cm.region;
    setDefaultConsentState(o.d.cmd);
    if (debug) log('info','Consent Default before Update', 'Default', JSON.parse(JSON.stringify(o.d.cmd)), 'Update', JSON.parse(JSON.stringify(o.d.cm)));
    let cm = JSON.parse(JSON.stringify(o.d.cm));
    Object.delete(cm, 'wait_for_update');
    Object.delete(cm, 'region'); // correct: updateConsentState has no region param
    updateConsentState(cm);
    if (debug) log('info','Consent Update after Default', JSON.parse(JSON.stringify(cm)));
  } else {
    setDefaultConsentState(o.d.cm);
    if (debug) log('info','Consent Default', JSON.parse(JSON.stringify(o.d.cm)));
  }
}

// Fire Microsoft Consent Mode
// Microsoft is a separate consent channel with its own vocabulary, not a mirror
// of Google's - and a push to it is not free. Measured in the live
// bat.bing.com/bat.js (2026-08-19): the FIRST consent push sets
// uetConfig.consent.enabled = true, and from then on shouldEnforce() returns
// false. That switches off two mechanisms UET runs by itself:
//   - its own enforcement in the EEA, the UK and Switzerland, where UET's
//     default is DENIED (elsewhere it is granted), and
//   - preEnforce(), which reads the Google Consent Mode state out of
//     window.google_tag_data.ics and subscribes to TCF about 1.5 s after load -
//     i.e. it would pick up what the Google half of THIS tag just set.
// Two rules follow, and they are the reason this branch looks the way it does.
if (o.c.ms_consent_mode) {
  // Rule 1: only 'granted' and 'denied' count as configured. The signal SELECTs
  // accept a GTM variable (macrosInSelect), so the value is whatever it
  // resolved to at runtime - an empty string from an unset variable must not
  // read as a state. In bat.js adStorageAllowed is computed as
  // ('denied' !== ad_storage) starting from an initial TRUE, so ANY value that
  // is not the literal 'denied' lands on granted.
  o.f.ms_val = function (v) {
    return (v === 'granted' || v === 'denied') ? v : '';
  };
  o.d.ms = {};
  var msSignals = ['ad_storage', 'ad_user_data', 'ad_personalization'];
  for (var mi=0; mi<msSignals.length; mi++) {
    var msv = o.f.ms_val(o.d.cm[msSignals[mi]]);
    if (msv) o.d.ms[msSignals[mi]] = msv;
  }
  // Rule 2: never push without ad_storage. It is the only signal UET evaluates
  // (ad_user_data and ad_personalization do not appear in bat.js at all), so a
  // payload without it would disable the enforcement above AND leave the
  // visitor on granted - the worst of both. When ad_storage is not configured
  // here, sending NOTHING is the fail-closed branch, not the fail-open one:
  // UET then keeps its own default, which is denied and enforced in the
  // EEA/UK/CH, and can still adopt the Google Consent Mode state.
  if (o.d.ms.ad_storage) {
    const uetq = createQueue('uetq');
    if (o.c.cm_update) {
      uetq('consent', 'update', o.d.ms);
      if (debug) log('info','Microsoft UET Consent Update', JSON.parse(JSON.stringify(o.d.ms)));
    } else if (o.c.cm_update_after_default) {
      // A baseline is a baseline: all three denied, regardless of what the
      // update will carry. Building it from the signals that happen to be set
      // could leave ad_storage out of the very default the mode exists for.
      // UET has no region parameter - the Microsoft baseline is global, only
      // the Google default is region-scoped.
      o.d.msd = {};
      for (var mj=0; mj<msSignals.length; mj++) o.d.msd[msSignals[mj]] = 'denied';
      uetq('consent', 'default', o.d.msd);
      uetq('consent', 'update', o.d.ms);
      if (debug) log('info','Microsoft UET Consent', 'Default', JSON.parse(JSON.stringify(o.d.msd)), 'Update', JSON.parse(JSON.stringify(o.d.ms)));
    } else {
      // UET understands wait_for_update as well (bat.js caps it at 10000 ms).
      // The Google branch has already computed it under exactly this condition;
      // without passing it on, UET would fire hits carrying the default state
      // during the window the integrator asked it to wait.
      if (o.d.cm.wait_for_update) o.d.ms.wait_for_update = o.d.cm.wait_for_update;
      uetq('consent', 'default', o.d.ms);
      if (debug) log('info','Microsoft UET Consent Default', JSON.parse(JSON.stringify(o.d.ms)));
    }
  } else if (debug) {
    log('info','Microsoft UET Consent skipped - ad_storage is not configured, so UET keeps its own default and its own enforcement');
  }
  // Clarity is all-or-nothing: Microsoft documents BOTH consentv2 fields as
  // required. Sending only one would be a call missing a required field, and
  // filling the other one in would deny a signal the integrator never
  // configured - Clarity has its own project-level consent setting to fall back
  // on. Note the ad_Storage / analytics_Storage casing is Microsoft's own.
  var clrAd = o.f.ms_val(o.d.cm.ad_storage);
  var clrAn = o.f.ms_val(o.d.cm.analytics_storage);
  if (clrAd && clrAn) {
    const clarityFct = () => {
      const clarity = copyFromWindow('clarity');
      if (clarity) return clarity;
      setInWindow('clarity', function() { callInWindow('clarity.q.push', arguments); });
      createQueue('clarity.q');
      return copyFromWindow('clarity');
    };
    const clarity = clarityFct();
    o.d.clr = { ad_Storage: clrAd, analytics_Storage: clrAn };
    clarity('consentv2', o.d.clr);
    if (debug) log('info','Microsoft Clarity Consent', JSON.parse(JSON.stringify(o.d.clr)));
  } else if (debug) {
    log('info','Microsoft Clarity Consent skipped - consentv2 needs both ad_Storage and analytics_Storage');
  }
}

// Set aGTM.d.cm
setInWindow('aGTM.d.cm', JSON.parse(JSON.stringify(o.d.cm)), true);

// Call data.gtmOnSuccess when the tag is finished.
data.gtmOnSuccess();


