scenarios:
- name: Anchor click fires the configured event with a click action
  code: |-
    let fired = null, cb = null;
    mock('callInWindow', function(fn) {
      if (fn === 'aGTM.f.addElLst') { cb = arguments[3]; return; }
      if (fn === 'aGTM.f.observer') { return; }
